const items = $input.all();

const results = items.map((item, i) => {
  const text = (item.json?.text || "").toLowerCase();

  let intent = "unknown";
  let reason = "no_clear_signal";

  if (
    text.includes("pricing") ||
    text.includes("price") ||
    text.includes("consultation") ||
    text.includes("service") ||
    text.includes("guidance")
  ) {
    intent = "service_or_pricing_interest";
    reason = "explicit_service_keywords";
  }

  if (
    text.includes("take care") ||
    text.includes("ok") ||
    text.includes("understood")
  ) {
    intent = "conversation_closed";
    reason = "polite_closure";
  }

  if (
    text.includes("fraud") ||
    text.includes("rude") ||
    text.includes("limitation") ||
    text.includes("not tolerate")
  ) {
    intent = "negative_or_hostile";
    reason = "negative_language";
  }

  if (
    text.includes("only for spiritual") ||
    text.includes("dedicated only") ||
    text.includes("cannot help with this topic")
  ) {
    intent = "off_topic_or_time_waster";
    reason = "boundary_enforcement";
  }

  return {
    json: {
      index: i + 1,
      original_text: item.json.text || "",
      intent,
      reason,
      should_follow_up:
        intent === "service_or_pricing_interest",
      should_stop:
        intent === "off_topic_or_time_waster" ||
        intent === "negative_or_hostile" ||
        intent === "conversation_closed",
      processed_at: new Date().toISOString()
    }
  };
});

return results;

const items = $input.all();

// Convert UTC ($now) to IST
const utcNow = new Date($now);
const istNow = new Date(utcNow.getTime() + (5.5 * 60 * 60 * 1000));

const results = items.map((item) => {
  const rawDate = item.json?.Date || "";
  let hoursPassed = null;

  try {
    // Input format: DD/MM/YYYY, h:mm:ss am/pm (IST)
    const cleaned = rawDate.replace(",", "");
    const [datePart, timePart, meridian] = cleaned.split(" ");

    let [day, month, year] = datePart.split("/");
    let [hour, minute, second] = timePart.split(":");

    hour = parseInt(hour, 10);
    minute = parseInt(minute, 10);
    second = parseInt(second || "0", 10);

    if (meridian.toLowerCase() === "pm" && hour !== 12) hour += 12;
    if (meridian.toLowerCase() === "am" && hour === 12) hour = 0;

    // Sheet time already in IST
    const sheetTimeIST = new Date(
      Number(year),
      Number(month) - 1,
      Number(day),
      hour,
      minute,
      second
    );

    // IST now minus sheet IST
    const diffMs = istNow.getTime() - sheetTimeIST.getTime();

    if (diffMs > 0) {
      hoursPassed = diffMs / (1000 * 60 * 60);
    }
  } catch (e) {
    hoursPassed = null;
  }

  return {
    json: {
      row_number: item.json.row_number,
      hours_passed: hoursPassed !== null ? Number(hoursPassed.toFixed(2)) : null,

      // 2 to 3 hours window
      is_between_2_and_3_hours:
        hoursPassed !== null &&
        hoursPassed >= 2 &&
        hoursPassed <= 3,

      // 24 to 26 hours window
      is_between_24_and_26_hours:
        hoursPassed !== null &&
        hoursPassed >= 24 &&
        hoursPassed <= 26,

      checked_at_ist: istNow.toISOString()
    }
  };
});

return results;

